INSERT OR IGNORE INTO question_bank_versions SELECT 'pre-provided-options-20261112',payload,revision,datetime('now') FROM question_bank WHERE id=1;
CREATE TABLE options_import_v4 (id INTEGER PRIMARY KEY, answer TEXT NOT NULL, options TEXT NOT NULL);
UPDATE question_bank SET payload=json_set(payload,'$.questions',json((SELECT json_group_array(json(CASE WHEN o.id IS NOT NULL AND json_extract(j.value,'$.answer')=o.answer THEN json_set(j.value,'$.options',json(o.options),'$.optionsSource','provided-question-bank') ELSE j.value END)) FROM json_each(question_bank.payload,'$.questions') j LEFT JOIN options_import_v4 o ON o.id=json_extract(j.value,'$.id')))),revision=revision+1 WHERE id=1;
DROP TABLE options_import_v4;
