INSERT INTO options_import_v4 VALUES(594,'التكلم في المهد، خلق الطير من الطين بإذن الله، إبراء الأكمه والأبرص، وإحياء الموتى بإذن الله','["فلق البحر بالعصا، وتحول العصا إلى ثعبان، وإخراج اليد بيضاء من غير سوء", "إخراج الناقة من الصخرة، وإنزال المطر بالدعاء، وتكليم الحوت", "التكلم في المهد، خلق الطير من الطين بإذن الله، إبراء الأكمه والأبرص، وإحياء الموتى بإذن الله", "تسخير الريح والجن، وفهم لغة الطير والنمل، وإلانة الحديد"]');
